WITH op AS (SELECT id FROM operators WHERE slug='bingo-auctions'),
sold AS (SELECT il.invoice_id, il.lot_id, il.winning_bid_cents, il.refunded_at, il.picked_up_at, l.category, l.lotted_by_worker, l.relisted_from_lot_id, l.relist_origin, l.auction_id lot_auc, w.name wh, (coalesce(l.category,'') ~* 'furniture') furn
  FROM invoice_lots il JOIN invoices i ON i.id=il.invoice_id JOIN lots l ON l.id=il.lot_id LEFT JOIN auctions a ON a.id=i.auction_id LEFT JOIN warehouses w ON w.id=a.warehouse_id, op
  WHERE i.operator_id=op.id AND i.created_at>=now()-interval '84 days' AND i.status::text <> 'canceled'),
au AS (SELECT DISTINCT ON (target_id, after_state->>'lot_id') target_id, (after_state->>'lot_id')::uuid lot_id, after_state->>'sub_reason' sr, lower(coalesce(after_state->>'reason_note','')) note FROM operator_audit_log, op WHERE operator_audit_log.operator_id=op.id AND action_type='invoice.refund_item' AND created_at>=now()-interval '90 days' ORDER BY target_id, after_state->>'lot_id', created_at),
r AS (SELECT s.*, au.sr, au.note FROM sold s LEFT JOIN au ON au.target_id=s.invoice_id AND au.lot_id=s.lot_id WHERE s.refunded_at IS NOT NULL AND s.picked_up_at IS NULL)
SELECT
(SELECT json_agg(x) FROM (SELECT coalesce(wh,'(invoice auction has no warehouse)') wh, count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL) refunded, count(*) sold, round(count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL)::numeric/count(*),3) rate FROM sold GROUP BY 1) x) by_wh_invoice,
(SELECT json_build_object('refunded_lot_auction_null', count(*) FILTER (WHERE lot_auc IS NULL), 'refunded_lot_auction_differs', count(*) FILTER (WHERE lot_auc IS NOT NULL)) FROM r) lot_auction_drift,
(SELECT json_build_object('notes', count(*) FILTER (WHERE note<>''), 'missing_cant_find', count(*) FILTER (WHERE note ~ 'miss|find|locat|not found|lost|gone'), 'broken_damaged', count(*) FILTER (WHERE note ~ 'broke|damag|crack|shatter|bent|torn|dent'), 'parts_incomplete', count(*) FILTER (WHERE note ~ 'part|piece|incomplete|hardware|screw'), 'wrong_desc', count(*) FILTER (WHERE note ~ 'wrong|descri|not the|different|size|color|colour'), 'defect_not_work', count(*) FILTER (WHERE note ~ 'defect|not work|doesn|dead|power'), 'sold_twice_dup', count(*) FILTER (WHERE note ~ 'dup|twice|double|already sold|sold to'), 'customer_req', count(*) FILTER (WHERE note ~ 'customer|cancel|changed|request|didn.t want|accident'), 'trash_dispose', count(*) FILTER (WHERE note ~ 'trash|dispos|toss|dump|destroy')) FROM r) note_buckets,
(SELECT json_agg(x) FROM (SELECT coalesce(sr,'none') sr, count(*) n, count(*) FILTER (WHERE note<>'') with_note, count(*) FILTER (WHERE note ~ 'miss|find|locat|not found|lost|gone') note_missing, count(*) FILTER (WHERE note ~ 'broke|damag|crack|shatter|bent|torn|dent') note_broken FROM r GROUP BY 1 ORDER BY 2 DESC) x) reason_vs_note,
(SELECT json_agg(x) FROM (SELECT furn, coalesce(sr,'none') sr, count(*) n FROM r GROUP BY 1,2 ORDER BY 1,3 DESC) x) furniture_vs_reason,
(SELECT json_agg(x) FROM (SELECT coalesce(relist_origin,'first listing') origin, count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL) refunded, count(*) sold, round(count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL)::numeric/count(*),3) rate FROM sold GROUP BY 1) x) by_relist_origin,
(SELECT json_agg(x) FROM (SELECT coalesce(left(md5(lotted_by_worker::text),6),'(no worker)') lotter, furn, count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL) refunded, count(*) sold, round(count(*) FILTER (WHERE refunded_at IS NOT NULL AND picked_up_at IS NULL)::numeric/count(*),3) rate FROM sold WHERE relisted_from_lot_id IS NULL GROUP BY 1,2 HAVING count(*)>=80 ORDER BY 2,5 DESC) x) lotter_first_listing_by_furn
